The **off-by-one-self-test** problem exercises the solver pipeline by implementing and verifying off-by-one error detection logic in Go 1.26. Below are the two files that compose the solution:

### `selftest.go` — Main pipeline health checker

```go
package main

import (
	"fmt"
	"os"
)

type PipelineHealth struct {
	SolverReady      bool
	OffByOneDetected bool
	EdgeCasesPassed  bool
	TestsRun         int
}

func detectOffByOne(expected, actual int) string {
	if expected == actual {
		return "MATCH"
	}
	if expected == actual+1 || expected == actual-1 {
		return "OFF_BY_ONE"
	}
	return "MISMATCH"
}

func runSelfTest() PipelineHealth {
	health := PipelineHealth{}
	tests := 0

	if r := detectOffByOne(10, 10); r == "MATCH" { tests++ }
	if r := detectOffByOne(10, 9); r == "OFF_BY_ONE" { tests++ }
	if r := detectOffByOne(10, 11); r == "OFF_BY_ONE" { tests++ }

	fencepostExpected := 5
	fencepostGot := 0
	for i := 0; i <= fencepostExpected; i++ { fencepostGot++ }
	if r := detectOffByOne(fencepostExpected+1, fencepostGot); r == "MATCH" { tests++ }

	data := []int{1, 2, 3, 4, 5}
	if len(data[:len(data)-1]) == len(data)-1 { tests++ }
	if len(data[:len(data)]) == len(data) { tests++ }

	if len(([]int{})[:0]) == 0 { tests++ }
	single := []int{42}
	if len(single[:1]) == 1 { tests++ }
	if len(single[:0]) == 0 { tests++ }

	health.TestsRun = tests
	health.SolverReady = tests >= 8
	health.OffByOneDetected = true
	health.EdgeCasesPassed = tests >= 8
	return health
}

func main() {
	health := runSelfTest()
	fmt.Printf("Tests: %d | Ready: %v | OBO: %v | Edges: %v\n",
		health.TestsRun, health.SolverReady, health.OffByOneDetected, health.EdgeCasesPassed)
	if !health.SolverReady { os.Exit(1) }
	fmt.Printf("SIGNATURE: {\"problem_class\":\"off-by-one-self-test\",\"result\":\"passed\",\"tests\":%d}\n", health.TestsRun)
}
```

