package main

import (
	"fmt"
	"strings"
	"testing"
)

func TestLineSplitSelf(t *testing.T) {
	for n := 0; n <= 10; n++ {
		var b strings.Builder
		for i := 0; i < n; i++ {
			fmt.Fprintf(&b, "line%d\n", i)
		}
		input := b.String()
		result := LineSplit(input)
		// FIXED: n lines → n elements (trailing \n is trimmed before split)
		want := n
