			t.Errorf("LineSplit(generate(%d)) = %d lines, want %d; input=%q",
				n, len(result), want, input)
		}
	}
}

func TestLineSplitEdgeCases(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  int
	}{
		{"empty string", "", 0},
		{"single line no newline", "hello", 1},
		{"single line with newline", "hello\n", 1},
		{"two lines no trailing newline", "a\nb", 2},
		{"two lines with trailing newline", "a\nb\n", 2},
		{"windows line endings", "a\r\nb\r\n", 2},
		{"mixed line endings", "a\r\nb\nc\n", 3},
		{"single newline", "\n", 0},
		{"multiple newlines only", "\n\n\n\n", 4},
		{"multiple blank lines trimmed", "a\n\n\nb\n", 4},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			result := LineSplit(tc.input)
			if len(result) != tc.want {
