// Page: zero-based paging; a page starting exactly at len(items) is empty, never a panic.
func Page(items []int, page, pageSize int) []int {
    if pageSize <= 0 || page < 0 || len(items) == 0 {
        return []int{}
    }
    start := page * pageSize
    if start >= len(items) {            // >=, not >: start==len must be empty
        return []int{}
    }
    end := start + pageSize
    if end > len(items) {
        end = len(items)
    }
    return items[start:end]
}

