    if b < a {
        return 0
    }
    return b - a + 1
}

// Clamp: endpoints inclusive; degenerate [lo,hi] with lo==hi is valid.
func Clamp(v, lo, hi int) int {
    if v < lo { return lo }
    if v > hi { return hi }
    return v
}

